/* Open the correct article in the Bootstrap modal */
document.querySelectorAll(".read-more-btn").forEach(button => {
    button.addEventListener("click", function () {
        const article = newsArticles[Number(this.dataset.article)];
        if (!article) return;

        document.getElementById("newsModalTitle").textContent = article.title;
        document.getElementById("newsModalDate").textContent = article.date;

        const image = document.getElementById("newsModalImage");
        image.src = article.image;
        image.alt = article.alt;

        const articleContent = document.getElementById("newsModalArticle");
        articleContent.replaceChildren();

        article.paragraphs.forEach(paragraph => {
            const p = document.createElement("p");
            p.textContent = paragraph;
            articleContent.appendChild(p);
        });

        const sourceLink = document.getElementById("newsModalSource");
        if (article.source) {
            sourceLink.href = article.source;
            sourceLink.hidden = false;
        } else {
            sourceLink.hidden = true;
            sourceLink.removeAttribute("href");
        }
    });
});
